package com.yeyamo_mobile.api.partner_service.application;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.yeyamo_mobile.api.partner_service.application.port.*;import com.yeyamo_mobile.api.partner_service.domain.model.*;import com.yeyamo_mobile.api.partner_service.domain.port.*;
class PartnerApprovalContractTests{@Test void approvalEventCarriesAuthOwnerId(){PartnerRepository partners=mock(PartnerRepository.class);PartnerDocumentRepository documents=mock(PartnerDocumentRepository.class);PartnerOutboxPort outbox=mock(PartnerOutboxPort.class);Partner p=Partner.create("42","Yeyamo",BusinessType.COMPANY,"c@y.test");p.update("Yeyamo",null,BusinessType.COMPANY,"RC-1",null,"c@y.test",null,null,null);p.submit(1);when(partners.findById(p.getId())).thenReturn(Optional.of(p));when(partners.save(any())).thenAnswer(i->i.getArgument(0));PartnerService service=new PartnerService(partners,documents,mock(DocumentStoragePort.class),outbox,mock(KycPolicy.class),1000);service.applyDecision(p.getId(),PartnerStatus.APPROVED,"OK",5,"req-3");@SuppressWarnings("unchecked")ArgumentCaptor<Map<String,Object>>payload=ArgumentCaptor.forClass(Map.class);verify(outbox).append(eq("partner.approved"),eq(p.getId()),eq("admin-service"),eq("req-3"),payload.capture());assertThat(payload.getValue().get("ownerUserId")).isEqualTo("42");}}
